(function () {
    var domain = "Koha";

    // English, untranslated: two forms, singular for 1
    var english_plural_forms = "nplurals=2; plural=(n != 1);";
    var locale_data = { "": { "Plural-Forms": english_plural_forms } };

    // locale_data.js, generated by misc/translator/po2json, puts the
    // msgid_plural before the translations: Tannin expects the translations
    // only
    if (typeof json_locale_data !== "undefined" && json_locale_data[domain]) {
        var data = json_locale_data[domain];
        for (var key in data) {
            if (key === "") {
                if (data[key]["Plural-Forms"]) locale_data[""] = data[key];
            } else {
                locale_data[key] = data[key].slice(1);
            }
        }
    }

    var tannin = new Tannin({ Koha: locale_data });

    function translate(msgctxt, msgid, msgid_plural, count) {
        var key = msgctxt ? msgctxt + "\u0004" + msgid : msgid;
        var translations = locale_data[key];
        // An untranslated string is in English: use the English plural forms
        if (count !== undefined && !(translations && translations[0])) {
            return count != 1 ? msgid_plural : msgid;
        }
        return tannin.dcnpgettext(domain, msgctxt, msgid, msgid_plural, count);
    }

    Koha.i18n = {
        gt: {
            gettext: function (msgid) {
                return translate(undefined, msgid);
            },
            ngettext: function (msgid, msgid_plural, count) {
                return translate(undefined, msgid, msgid_plural, count);
            },
            pgettext: function (msgctxt, msgid) {
                return translate(msgctxt, msgid);
            },
            npgettext: function (msgctxt, msgid, msgid_plural, count) {
                return translate(msgctxt, msgid, msgid_plural, count);
            },
        },

        expand: function (text, vars) {
            var replace_callback = function (match, name) {
                return name in vars ? vars[name] : match;
            };
            return text.replace(/\{(.*?)\}/g, replace_callback);
        },
    };
})();

function __(msgid) {
    return Koha.i18n.gt.gettext(msgid);
}

function __x(msgid, vars) {
    return Koha.i18n.expand(__(msgid), vars);
}

function __n(msgid, msgid_plural, count) {
    return Koha.i18n.gt.ngettext(msgid, msgid_plural, count);
}

function __nx(msgid, msgid_plural, count, vars) {
    return Koha.i18n.expand(__n(msgid, msgid_plural, count), vars);
}

function __p(msgctxt, msgid) {
    return Koha.i18n.gt.pgettext(msgctxt, msgid);
}

function __px(msgctxt, msgid, vars) {
    return Koha.i18n.expand(__p(msgctxt, msgid), vars);
}

function __np(msgctxt, msgid, msgid_plural, count) {
    return Koha.i18n.gt.npgettext(msgctxt, msgid, msgid_plural, count);
}

function __npx(msgctxt, msgid, msgid_plural, count, vars) {
    return Koha.i18n.expand(__np(msgctxt, msgid, msgid_plural, count), vars);
}
